INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (10056, "カリン", 190804, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 1.539, 10056008, 1, -363, "2021/01/18 14:59:59", 3, 2, "2020/12/31 12:00:00", 0, 56);
