INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, 20026001, 2, -416.5, "2030/01/01 14:59:59", 1, 1, "2022/04/18 15:00:00", 0, 53);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, 20026002, 2, -416.5, "2030/01/01 14:59:59", 2, 1, "2022/04/18 15:00:00", 0, 53);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, 20026003, 2, -416.5, "2030/01/01 14:59:59", 3, 1, "2022/04/18 15:00:00", 0, 54);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "報酬がもらえますよ！\nチェックしてみてください", 0, 20026004, 2, -416.5, "2030/01/01 14:59:59", 4, 2, "2022/04/18 15:00:00", 0, 54);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 0, 20026005, 1, -416.5, "2030/01/01 14:59:59", 5, 1, "2022/04/18 15:00:00", 0, 57);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 5.506, 20026006, 2, -363, "2030/01/01 14:59:59", 1, 1, "2022/04/18 15:00:00", 0, 55);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 1.216, 20026007, 1, -363, "2030/01/01 14:59:59", 2, 2, "2022/04/18 15:00:00", 0, 55);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 1.539, 20026008, 1, -363, "2030/01/01 14:59:59", 3, 2, "2022/04/18 15:00:00", 0, 56);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (20026, "カリン", 190801, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 1.875, 20026009, 1, -363, "2030/01/01 14:59:59", 4, 2, "2022/04/18 15:00:00", 0, 56);
